package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.*; import com.example.ecommerce.model.Product; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException; import java.math.BigDecimal;
@WebServlet("/admin/products") public class AdminProductServlet extends HttpServlet{ProductDAO dao=new ProductDAO();CategoryDAO cdao=new CategoryDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String action=req.getParameter("action");if("delete".equals(action)){dao.deactivate(Integer.parseInt(req.getParameter("id")));resp.sendRedirect(req.getContextPath()+"/admin/products");return;}if("edit".equals(action))req.setAttribute("product",dao.findById(Integer.parseInt(req.getParameter("id"))));req.setAttribute("categories",cdao.findActive());req.setAttribute("products",dao.findAll());req.getRequestDispatcher("/WEB-INF/views/admin/products.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{Product p=new Product();String id=req.getParameter("id");if(id!=null&&!id.isEmpty())p.setId(Integer.parseInt(id));p.setCategoryId(Integer.parseInt(req.getParameter("categoryId")));p.setName(req.getParameter("name"));p.setDescription(req.getParameter("description"));p.setPrice(new BigDecimal(req.getParameter("price")));p.setStock(Integer.parseInt(req.getParameter("stock")));p.setImageUrl(req.getParameter("imageUrl"));p.setActive("on".equals(req.getParameter("active")));dao.save(p);resp.sendRedirect(req.getContextPath()+"/admin/products");}catch(Exception e){throw new ServletException(e);}}}
